49	    if (ret >= 0) {
50	      mount_state = 1;
51	    } else {
52	      _info("micro_sd: mount failed: %d\n", ret);
53	    }
54	
55	    mrcio_state = 1;
56	  } else {
57	    if (mount_state == 1) {
58	      //UMOUNT_NOFOLLOW MNT_EXPIRE MNT_DETACH MNT_FORCE
