160	int audio_init(enum audio_mode_e mode, uint8_t channels, uint8_t bps,
161	               uint32_t sample_rate, uint8_t chmap)
162	{
163	  struct stat st;
164	  int ret;
165	
166	  if (g_audio_ctx.initialized)
167	    {
168	      printf("[audio] ERROR: Already initialized\n");
169	      return -EBUSY;
170	    }
171	
172	  printf("[audio] Initializing mode=%d, %luHz, %ubit, %uch\n",
173	         mode, (unsigned long)sample_rate, bps, channels);
174	
175	  memset(&g_audio_ctx, 0, sizeof(g_audio_ctx));
176	  g_audio_ctx.mode = mode;
177	  g_audio_ctx.channels = channels;
178	  g_audio_ctx.bps = bps;
179	  g_audio_ctx.sample_rate = sample_rate;
180	  g_audio_ctx.chmap = chmap;
181	
182	  /* Create recorder */
183	  g_audio_ctx.recorder = nxrecorder_create();
184	  if (!g_audio_ctx.recorder)
185	    {
186	      printf("[audio] ERROR: Failed to create recorder\n");
187	      return -ENOMEM;
188	    }
189	
190	  /* Set callback for record mode only */
191	  if (mode == AUDIO_MODE_RECORD)
192	    {
193	      g_audio_ctx.recorder->ops = &g_record_ops;
194	    }
195	  else /* AUDIO_MODE_LOOPBACK */
196	    {
197	      /* Check /var/pipe exists */
198	      if (stat("/var/pipe", &st) < 0)
199	        {
200	          printf("[audio] ERROR: /var/pipe not found\n");
201	          nxrecorder_release(g_audio_ctx.recorder);
202	          return -ENOENT;
203	        }
204	
205	      /* Create FIFO - recorder will write to it directly */
206	      unlink(LOOPBACK_FIFO);
207	      ret = mkfifo(LOOPBACK_FIFO, 0666);
208	      if (ret < 0 && errno != EEXIST)
209	        {
210	          printf("[audio] ERROR: mkfifo failed: %d\n", errno);
211	          nxrecorder_release(g_audio_ctx.recorder);
212	          return -errno;
213	        }
214	      printf("[audio] FIFO created: %s\n", LOOPBACK_FIFO);
215	
216	      /* Create player */
217	      g_audio_ctx.player = nxplayer_create();
218	      if (!g_audio_ctx.player)
219	        {
220	          printf("[audio] ERROR: Failed to create player\n");
221	          nxrecorder_release(g_audio_ctx.recorder);
222	          unlink(LOOPBACK_FIFO);
223	          return -ENOMEM;
224	        }
225	
226	      nxplayer_setdevice(g_audio_ctx.player, "/dev/audio/pcm0p");
227	
228	      /* Start player in background thread (will block on FIFO open) */
229	      struct player_init_args_s *args = malloc(sizeof(*args));
230	      if (!args)
231	        {
232	          printf("[audio] ERROR: malloc failed\n");
233	          nxplayer_release(g_audio_ctx.player);
234	          g_audio_ctx.player = NULL;
235	          nxrecorder_release(g_audio_ctx.recorder);
236	          unlink(LOOPBACK_FIFO);
237	          return -ENOMEM;
238	        }
239	
240	      args->player = g_audio_ctx.player;
241	      args->filepath = LOOPBACK_FIFO;
242	      args->channels = channels;
243	      args->bps = bps;
244	      args->sample_rate = sample_rate;
245	      args->chmap = chmap;
246	
247	      g_audio_ctx.player_thread_running = true;
248	      ret = pthread_create(&g_audio_ctx.player_thread, NULL,
249	                          player_init_thread, args);
250	      if (ret != 0)
251	        {
252	          printf("[audio] ERROR: pthread_create failed: %d\n", ret);
253	          free(args);
254	          g_audio_ctx.player_thread_running = false;
255	          nxplayer_release(g_audio_ctx.player);
256	          g_audio_ctx.player = NULL;
257	          nxrecorder_release(g_audio_ctx.recorder);
258	          unlink(LOOPBACK_FIFO);
259	          return -ret;
260	        }
261	
262	      printf("[audio] Player thread started (waiting for recorder)\n");
263	
264	      /* Give thread time to enter blocking state */
265	      usleep(100000);  /* 100ms */
266	    }
267	
268	  g_audio_ctx.initialized = true;
269	  printf("[audio] Initialization complete\n");
270	  return OK;
271	}
