/* ================================================================
 * MUSIC SUBPAGE — ported from LVGL music demo (lv_demo_music)
 * Light theme, no intro animation, DM() scaled for 1920x1200.
 * Track list is scanned from the TF card (/sdcard/music), filtered
 * to the supported formats (mp3/flac/ogg/aac/wav).
 * ================================================================ */

#define DM_MAX_TRACKS   64
#define DM_MUSIC_DIR    "/sdcard/music"

struct dm_track
{
    char     path[256];   /* full file path */
    char     title[128];  /* filename without extension */
    uint32_t length;      /* seconds; 0 = unknown */
};

static struct dm_track dm_tracks[DM_MAX_TRACKS];
static uint32_t        dm_track_count;

static lv_obj_t    *music_play_btn;
static lv_obj_t    *music_play_icon;
static lv_obj_t    *music_slider;
static lv_obj_t    *music_time_lbl;
static lv_obj_t    *music_time_total_lbl;
static lv_obj_t    *music_title_lbl;
static lv_obj_t    *music_artist_lbl;
static lv_obj_t    *music_playlist_overlay;   /* full-screen, hidden */
static lv_obj_t    *music_list_cont;          /* list inside overlay */
static lv_obj_t    *music_empty_lbl;          /* "no tracks" hint */
static lv_obj_t    *music_active_btn;
static uint32_t     music_track_id;
static bool         music_playing;

static void music_play(uint32_t id);
static void music_resume(void);
static void music_pause(void);
static void music_album_next(bool next);
static void music_update_track_info(void);
static void music_playlist_toggle_cb(lv_event_t *e);
static void music_playlist_toggle(void);

/* Scan /sdcard/music for supported audio files (mp3/flac/ogg/aac/wav).
 * Returns the number of tracks found. Call each time the playlist
 * overlay opens so newly copied songs appear. */
static uint32_t music_scan_tracks(void)
{
    DIR *dir;
    struct dirent *ent;
    const char *supported[] = { ".mp3", ".flac", ".ogg", ".aac", ".wav" };
    uint32_t count = 0;

    dm_track_count = 0;
    dir = opendir(DM_MUSIC_DIR);
    if (dir == NULL)
        return 0;

    while ((ent = readdir(dir)) != NULL && count < DM_MAX_TRACKS)
    {
        const char *dot = strrchr(ent->d_name, '.');
        int i, ok = 0;

        if (dot == NULL || dot == ent->d_name)
            continue;

        for (i = 0; i < 5; i++)
        {
            if (strcasecmp(dot, supported[i]) == 0)
            {
                ok = 1;
                break;
            }
        }
        if (!ok)
            continue;

        snprintf(dm_tracks[count].path, sizeof(dm_tracks[count].path),
                 "%s/%s", DM_MUSIC_DIR, ent->d_name);
        snprintf(dm_tracks[count].title, sizeof(dm_tracks[count].title),
                 "%.*s", (int)(dot - ent->d_name), ent->d_name);
        dm_tracks[count].length = 0;   /* duration filled by decoder layer */
        count++;
    }

    closedir(dir);
    dm_track_count = count;
    return count;
}

