#ifdef CONFIG_LUNCHER_DM_APP
static struct nxplayer_s *g_music_player;

static void music_audio_start(const char *path)
{
    int ret;

    if (g_music_player == NULL)
    {
        g_music_player = nxplayer_create();
        if (g_music_player == NULL) return;
        nxplayer_setdevice(g_music_player, "/dev/audio/pcm0p");
    }

    nxplayer_stop(g_music_player);
    ret = nxplayer_playfile(g_music_player, path, 0, 0);
    if (ret != OK)
        lv_label_set_text(music_artist_lbl, "Playback error");
}

static void music_audio_pause(void)
{
    if (g_music_player) nxplayer_pause(g_music_player);
}

static void music_audio_resume(void)
{
    if (g_music_player) nxplayer_resume(g_music_player);
}

static void music_audio_stop(void)
{
    if (g_music_player) nxplayer_stop(g_music_player);
}
#else
static void music_audio_start(const char *path) { (void)path; }
static void music_audio_pause(void) { }
static void music_audio_resume(void) { }
static void music_audio_stop(void) { }
