        ret = nxplayer_setdevice(g_music_player, "/dev/audio/pcm0p");
        printf("[music] setdevice pcm0p ret=%d\n", ret);
    }

    ret = nxplayer_playfile(g_music_player, path, 0, 0);
    printf("[music] playfile ret=%d errno=%d\n", ret, errno);
    if (ret != OK)
        lv_label_set_text(music_artist_lbl, "Playback error");
}

