{
	int32_t own_set = 0;
	clock_t time = HAL_Ticks() + HAL_MSecsToTicks(1000) + 1;

	while (!(mci_readl(host, SDXC_REG_GCTRL) & SDXC_MemAccessDone) && (HAL_TimeBefore(HAL_Ticks(), time)));
